<?php
require 'page-guard.php';if($_SESSION['user-role']!=='administrator'){http_response_code(403);exit('Administrators only.');}
require '../config/db_conn.php';require '../includes/teacher-profile-schema.php';require '../includes/teacher-assignment-schema.php';require '../includes/student-placement-options.php';require '../includes/section-catalog-schema.php';ensureTeacherProfileColumns($conn);ensureSectionCatalogColumns($conn);seedDefaultTeacherSections($conn);ensureTeacherAssignmentSchema($conn);
$firstName=trim($_POST['first_name']??'');$lastName=trim($_POST['last_name']??'');$name=trim($firstName.' '.$lastName);$user=trim($_POST['teacher_user']??'');$pass=$_POST['teacher_pass']??'';$confirm=$_POST['teacher_confirm']??'';$assignments=postedTeacherAssignments($conn);
if($firstName===''||$lastName===''||!filter_var($user,FILTER_VALIDATE_EMAIL)||strlen($pass)<8||$pass!==$confirm||!$assignments)exit('Please provide valid teacher details and at least one valid grade and section assignment.');
$primary=$assignments[0];$hash=password_hash($pass,PASSWORD_DEFAULT);$stmt=$conn->prepare('INSERT INTO teachers (TEACHER_USER,TEACHER_PASS,TEACHER_NAME,FIRST_NAME,LAST_NAME,GRADE,STRAND,SECTION,SUBJECT) VALUES (?,?,?,?,?,?,?,?,?)');$stmt->bind_param('sssssisss',$user,$hash,$name,$firstName,$lastName,$primary['grade'],$primary['strand'],$primary['section'],$primary['subject']);
if(!$stmt->execute()){http_response_code(409);exit('That teacher username already exists.');}replaceTeacherAssignments($conn,(int)$conn->insert_id,$assignments);$_SESSION['toast']=['message'=>'Teacher account created successfully.','type'=>'success'];header('Location: teacher-list.php');exit;
